from __future__ import annotations

import base64
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
WEB = ROOT / "web"
OUTPUT = ROOT / "embedded_assets.py"
FILES = ("index.html", "styles.css", "app.js", "favicon.svg")

lines = [
    '"""Generated by packaging/embed_web_assets.py. Do not edit manually."""',
    "",
    "WEB_ASSETS_B64 = {",
]
for name in FILES:
    encoded = base64.b64encode((WEB / name).read_bytes()).decode("ascii")
    lines.append(f"    {name!r}: {encoded!r},")
lines.extend(["}", ""])
OUTPUT.write_text("\n".join(lines), encoding="ascii")
print(f"Embedded {len(FILES)} web assets into {OUTPUT}")
